function certify_novelty(C, x, eps):
    assert C is nonempty
    best <- dist(x, C[0]); near <- C[0]
    for c in C[1:]:
        d <- dist(x, c)
        if d < best: best <- d; near <- c
    certified <- (eps > 0) and (eps <= best)
    return (certified, best, near)

function streaming_novelties(stream, queries):
    current[i] <- +infinity for each query i
    for a in stream:
        for i, q in enumerate(queries):
            current[i] <- min(current[i], dist(q, a))
            record current[i]
    return recorded history

function packing_upper_bound(side R, eps, dim d):
    cells_per_axis <- ceil(R / (eps / sqrt(d)))
    return cells_per_axis ^ d
function greedy_separated(points, eps):
    chosen <- []
    for p in points:
        if dist(p, c) >= eps for all c in chosen:
            append p to chosen
    return chosen
